style.css:
/* Hide original words */
a[href*="connections"], a[href*="connect"] span,
a[href*="connections"], a[href*="connect"] {
  font-size: 0 !important;
  position: relative;
}

/* Replace "Connections" with "Friends" */
a[href*="connections"]::after,
a[href*="connections"] span::after {
  content: "Friends";
  font-size: initial !important;
  color: inherit;
  position: absolute;
  left: 0;
  top: 0;
}

/* Replace "Connect" with "Add Friends" */
a[href*="connect"]::after,
a[href*="connect"] span::after {
  content: "Add Friends";
  font-size: initial !important;
  color: inherit;
  position: absolute;
  left: 0;
  top: 0;
}
